cd data && python -c "
import pandas as pd, numpy as np
b=pd.read_csv('back-stats.csv')
slots=[f'pct_appearances_{i}' for i in range(1,10)]
b['dec']=(b.season//10)*10
attrs=['average','power','walks','speed']
rows=[]
for s in slots:
    for era,g in b.groupby('era'):
        d={'slot':s,'era':era}
        for a in attrs:
            d[a]=np.average(g[a],weights=g[s])
        rows.append(d)
print(pd.DataFrame(rows).pivot(index='slot',columns='era',values=attrs).round(2).to_string())
print()
# weight by pct*pa
rows=[]
for s in slots:
    for era,g in b.groupby('era'):
        d={'slot':s,'era':era}
        for a in attrs:
            d[a]=np.average(g[a],weights=g[s]*g.pa)
        rows.append(d)
print(pd.DataFrame(rows).pivot(index='slot',columns='era',values=attrs).round(2).to_string())
"

